import java.util.concurrent.*;

public class BlockingQueueDemo {
    public static void main(String[] args) throws InterruptedException {
        // 1. ArrayBlockingQueue: Bounded with fixed array
        BlockingQueue<String> arrayQueue = new ArrayBlockingQueue<>(10);

        // 2. LinkedBlockingQueue: Optionally bounded with dual locks
        BlockingQueue<String> linkedQueue = new LinkedBlockingQueue<>(100);

        // 3. PriorityBlockingQueue: Orders by natural sorting or comparator
        BlockingQueue<Task> priorityQueue = new PriorityBlockingQueue<>();

        // 4. DelayQueue: Elements must implement Delayed
        BlockingQueue<ScheduledTask> delayQueue = new DelayQueue<>();

        // 5. SynchronousQueue: Zero capacity direct hand-off
        BlockingQueue<String> syncQueue = new SynchronousQueue<>();

        // Demonstration of safe producer-consumer hand-off
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(() -> {
            try {
                syncQueue.put("Payload via SynchronousQueue");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        System.out.println(syncQueue.take());
        executor.shutdown();
    }

    static class Task implements Comparable<Task> {
        private final int priority;
        Task(int priority) { this.priority = priority; }
        @Override public int compareTo(Task o) { return Integer.compare(this.priority, o.priority); }
    }

    static class ScheduledTask implements Delayed {
        private final long triggerTime;
        ScheduledTask(long delayMs) { this.triggerTime = System.currentTimeMillis() + delayMs; }
        @Override public long getDelay(TimeUnit unit) { return unit.convert(triggerTime - System.currentTimeMillis(), TimeUnit.MILLISECONDS); }
        @Override public int compareTo(Delayed o) { return Long.compare(this.getDelay(TimeUnit.MILLISECONDS), o.getDelay(TimeUnit.MILLISECONDS)); }
    }
}
